module UART_Simple_Protocol_Wrapper
   (out,
    tx_OBUF,
    E,
    reg_SCON0_WRITE,
    reg_SBUF0_WRITE,
    Q,
    ri_OBUF,
    rst_IBUF,
    clk,
    \reg_TCON_reg[6]_0 ,
    reg_SCON0_WRITE_reg_0,
    reg_SBUF0_WRITE_reg_0,
    rx_IBUF,
    \reg_TL1_reg[7]_0 ,
    D,
    \reg_TH1_reg[7]_0 ,
    \reg_SBUF0_reg[7]_0 ,
    \reg_SCON0_reg[7]_0 ,
    \reg_SCON0_reg[7]_1 );
  output [7:0]out;
  output tx_OBUF;
  output [0:0]E;
  output reg_SCON0_WRITE;
  output reg_SBUF0_WRITE;
  output [0:0]Q;
  output ri_OBUF;
  input rst_IBUF;
  input clk;
  input \reg_TCON_reg[6]_0 ;
  input reg_SCON0_WRITE_reg_0;
  input reg_SBUF0_WRITE_reg_0;
  input rx_IBUF;
  input [0:0]\reg_TL1_reg[7]_0 ;
  input [7:0]D;
  input [0:0]\reg_TH1_reg[7]_0 ;
  input [0:0]\reg_SBUF0_reg[7]_0 ;
  input [0:0]\reg_SCON0_reg[7]_0 ;
  input [7:0]\reg_SCON0_reg[7]_1 ;

  wire [0:0]E;
  wire [0:0]Q;
  wire clk;
  wire reg_SBUF0_WRITE;
  wire reg_SBUF0_WRITE_reg_0;
  (* RTL_KEEP = "true" *) wire [7:0]reg_SCON0;
  wire reg_SCON0_WRITE;
  wire reg_SCON0_WRITE_reg_0;
  wire [0:0]\reg_SCON0_reg[7]_0 ;
  wire [7:0]\reg_SCON0_reg[7]_1 ;
  wire \reg_TCON_reg[6]_0 ;
  wire ri_OBUF;
  wire rst_IBUF;
  wire rx_IBUF;
  wire tx_OBUF;
  wire [7:0]NLW_uart_inst_Q_UNCONNECTED;
  wire [7:0]\NLW_uart_inst_TL1_OUT_reg[7]_C_UNCONNECTED ;
  wire [7:0]\NLW_uart_inst_shift_reg_reg[7]_UNCONNECTED ;

  assign out[7] = reg_SCON0[7];
  assign out[4:3] = reg_SCON0[4:3];
  assign out[1:0] = reg_SCON0[1:0];
  FDCE #(
    .INIT(1'b0)) 
    reg_SBUF0_WRITE_reg
       (.C(clk),
        .CE(1'b1),
        .CLR(rst_IBUF),
        .D(reg_SBUF0_WRITE_reg_0),
        .Q(reg_SBUF0_WRITE));
  FDRE #(
    .INIT(1'b0)) 
    reg_SCON0_WRITE_reg
       (.C(clk),
        .CE(1'b1),
        .D(reg_SCON0_WRITE_reg_0),
        .Q(reg_SCON0_WRITE),
        .R(1'b0));
  (* KEEP = "yes" *) 
  FDCE #(
    .INIT(1'b0)) 
    \reg_SCON0_reg[0] 
       (.C(clk),
        .CE(\reg_SCON0_reg[7]_0 ),
        .CLR(rst_IBUF),
        .D(\reg_SCON0_reg[7]_1 [0]),
        .Q(reg_SCON0[0]));
  (* KEEP = "yes" *) 
  FDCE #(
    .INIT(1'b0)) 
    \reg_SCON0_reg[1] 
       (.C(clk),
        .CE(\reg_SCON0_reg[7]_0 ),
        .CLR(rst_IBUF),
        .D(\reg_SCON0_reg[7]_1 [1]),
        .Q(reg_SCON0[1]));
  (* KEEP = "yes" *) 
  FDCE #(
    .INIT(1'b0)) 
    \reg_SCON0_reg[3] 
       (.C(clk),
        .CE(\reg_SCON0_reg[7]_0 ),
        .CLR(rst_IBUF),
        .D(\reg_SCON0_reg[7]_1 [3]),
        .Q(reg_SCON0[3]));
  (* KEEP = "yes" *) 
  FDCE #(
    .INIT(1'b0)) 
    \reg_SCON0_reg[4] 
       (.C(clk),
        .CE(\reg_SCON0_reg[7]_0 ),
        .CLR(rst_IBUF),
        .D(\reg_SCON0_reg[7]_1 [4]),
        .Q(reg_SCON0[4]));
  (* KEEP = "yes" *) 
  FDCE #(
    .INIT(1'b0)) 
    \reg_SCON0_reg[7] 
       (.C(clk),
        .CE(\reg_SCON0_reg[7]_0 ),
        .CLR(rst_IBUF),
        .D(\reg_SCON0_reg[7]_1 [7]),
        .Q(reg_SCON0[7]));
  FDCE #(
    .INIT(1'b0)) 
    \reg_TCON_reg[6] 
       (.C(clk),
        .CE(1'b1),
        .CLR(rst_IBUF),
        .D(\reg_TCON_reg[6]_0 ),
        .Q(E));
  UART uart_inst
       (.E(E),
        .Q(NLW_uart_inst_Q_UNCONNECTED[7:0]),
        .\SFR_SCON0_OUT_reg[1]_0 (Q),
        .\SFR_SCON0_OUT_reg[1]_1 (reg_SCON0_WRITE),
        .\TL1_OUT_reg[7]_C (\NLW_uart_inst_TL1_OUT_reg[7]_C_UNCONNECTED [7:0]),
        .clk(clk),
        .out({reg_SCON0[7],reg_SCON0[4:3],reg_SCON0[1:0]}),
        .reg_SBUF0_WRITE(reg_SBUF0_WRITE),
        .ri_OBUF(ri_OBUF),
        .rst_IBUF(rst_IBUF),
        .rx_IBUF(rx_IBUF),
        .\shift_reg_reg[7] (\NLW_uart_inst_shift_reg_reg[7]_UNCONNECTED [7:0]),
        .tx_OBUF(tx_OBUF));
